
DELETE FROM `creature_properties` WHERE `build` = 18414 AND `entry` IN (40789, 41200, 54856, 54958, 55547, 55548, 55558, 55649, 55666, 55685, 55744, 55939, 56159, 56378, 56661, 56688, 57750, 57874, 60488, 61126, 61127, 61128, 61801);

-- The Wandering Isle (map 860): spellclick vehicles
DELETE FROM `npc_spellclick_spells` WHERE `npc_entry` IN (54635, 54993, 55083, 55918, 56739, 57431, 57626, 57710, 57741, 59497, 60770, 60877, 64507);

DELETE FROM `vehicle_accessories` WHERE `entry` = 56739;

-- The Wandering Isle (map 860): creature texts
DELETE FROM `npc_script_text` WHERE `entry` BETWEEN 11000 AND 11044;

-- The Wandering Isle (map 860): area phase auras
DELETE FROM `spell_area` WHERE `spell` IN (102393, 102395, 102398, 60922, 102403, 114611, 116421, 116571) AND `area` IN (5825, 5829, 5834, 5835, 5843, 5846, 5848, 5862);

-- The Wandering Isle (map 860): every creature spawn carries the column default faction 14 (Monster),
-- which overrides the properties faction on load and makes all NPCs hostile. Use the properties faction.
UPDATE `creature_spawns` s
JOIN `creature_properties` p ON p.`entry` = s.`entry` AND p.`build` = 18414
SET s.`faction` = p.`faction`
WHERE s.`map` = 860 AND s.`min_build` = 18414;

-- The Wandering Isle (map 860): Aysa Cloudsinger and Merchant Lorvo are missing the gossip flag
UPDATE `creature_properties` SET `npcflags` = 3 WHERE `build` = 18414 AND `entry` = 54567;
UPDATE `creature_properties` SET `npcflags` = 643 WHERE `build` = 18414 AND `entry` = 54943;

-- The Wandering Isle (map 860): the permanent training targets of the academy never die and never fight back
UPDATE `creature_properties` SET `isTrainingDummy` = 1 WHERE `build` = 18414 AND `entry` = 57873;

-- The Wandering Isle (map 860): kill credit properties of quest 29408 The Lesson of the Burning Scroll
DELETE FROM `creature_properties` WHERE `build` = 18414 AND `entry` IN (59570, 59591);


-- The Wandering Isle (map 860): class weapon racks (chest loot ids 40856..40864) of the quests
-- The Lesson of the Iron Bough (30027, 30033..30038) and the kill credits given when the weapons are equipped.
DELETE FROM `loot_gameobjects` WHERE `entryid` IN (40856, 40859, 40860, 40861, 40862, 40863, 40864);

DELETE FROM `creature_properties` WHERE `build` = 18414 AND `entry` IN (54139, 57849);

